export const CREDIT_COSTS = {
    TEXT_GENERATION_PER_TOKEN: 1 / 100, // 100,000 tokens = 1000 credits
    IMAGE_GENERATION_GEMINI: 50,
    IMAGE_GENERATION_IMAGEN: 300,
    AUDIO_GENERATION_PER_TOKEN: 1 / 100, // Treat audio text tokens same as text
    AUDIO_GENERATION_ELEVENLABS_INSTANT: 150,
    AUDIO_GENERATION_ALIGNED: 50,
    AUDIO_ALIGNMENT_AI33: 50,
    AUDIO_CLONING_MINIMAX: 500,
    VIDEO_GENERATION: 2500,
};

export function updateDynamicCreditCosts(newCosts: Partial<typeof CREDIT_COSTS>) {
    if (!newCosts) return;
    if (typeof newCosts.TEXT_GENERATION_PER_TOKEN === 'number') CREDIT_COSTS.TEXT_GENERATION_PER_TOKEN = newCosts.TEXT_GENERATION_PER_TOKEN;
    if (typeof newCosts.IMAGE_GENERATION_GEMINI === 'number') CREDIT_COSTS.IMAGE_GENERATION_GEMINI = newCosts.IMAGE_GENERATION_GEMINI;
    if (typeof newCosts.IMAGE_GENERATION_IMAGEN === 'number') CREDIT_COSTS.IMAGE_GENERATION_IMAGEN = newCosts.IMAGE_GENERATION_IMAGEN;
    if (typeof newCosts.AUDIO_GENERATION_ELEVENLABS_INSTANT === 'number') CREDIT_COSTS.AUDIO_GENERATION_ELEVENLABS_INSTANT = newCosts.AUDIO_GENERATION_ELEVENLABS_INSTANT;
    if (typeof newCosts.AUDIO_GENERATION_ALIGNED === 'number') CREDIT_COSTS.AUDIO_GENERATION_ALIGNED = newCosts.AUDIO_GENERATION_ALIGNED;
    if (typeof newCosts.AUDIO_CLONING_MINIMAX === 'number') CREDIT_COSTS.AUDIO_CLONING_MINIMAX = newCosts.AUDIO_CLONING_MINIMAX;
    if (typeof newCosts.VIDEO_GENERATION === 'number') CREDIT_COSTS.VIDEO_GENERATION = newCosts.VIDEO_GENERATION;
}

