export enum StyleIntent {
    CINEMATIC = 'cinematic',
    DOCUMENTARY = 'documentary',
    TECHNICAL = 'technical',
    ILLUSTRATED = 'illustrated',
    ANIMATED = 'animated',
    ABSTRACT = 'abstract'
}

